@push('scripts')<script>$(function(){var t=$('#accounting-audit-table'),a=$('#audit-action'),f=$('#audit-from'),to=$('#audit-to'),x=$.fn.dataTable.render.text();var dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.action=a.val();d.date_from=f.val();d.date_to=to.val()}},order:[[0,'desc']],buttons:[window.erpExcelButton(t,function(){return{action:a.val(),date_from:f.val(),date_to:to.val()}})],columns:[{data:'created_at',name:'audit_logs.created_at',render:x.display},{data:null,render:function(v,t,row){return x.display((row.user_name||'System')+(row.username?' · '+row.username:''))}},{data:'action',name:'audit_logs.action',render:x.display},{data:'subject_type',name:'audit_logs.subject_type',render:x.display},{data:'ip_address',name:'audit_logs.ip_address',render:x.display}]}));a.add(f).add(to).on('change keyup',function(){dt.ajax.reload()});$('#audit-reset').on('click',function(){a.val('');f.val('');to.val('');dt.ajax.reload()})});</script>@endpush
